<script setup lang="ts">
import {ref} from 'vue';import InputText from 'primevue/inputtext';import Button from 'primevue/button';import DataTable from 'primevue/datatable';import Column from 'primevue/column';import {api} from '../lib/api';import {useQuery} from '../composables/useQuery';import {date,initials} from '../lib/types';import QueryState from '../components/QueryState.vue';
const search=ref(''),cursor=ref<string|null>(null);const {data,loading,error,refresh}=useQuery(()=>api('/admin/audit-logs?'+new URLSearchParams({q:search.value,pageSize:'30',...(cursor.value?{cursor:cursor.value}:{})})),15000);
</script>
<template><div class="page-heading"><div><div class="eyebrow">TRUY VẾT & KIỂM SOÁT</div><h1>Nhật ký hoạt động<span class="green-text">.</span></h1><p>Mỗi quyết định đều có người thực hiện, thời điểm và lý do.</p></div><span class="date-pill"><i class="pi pi-lock"></i>Chỉ đọc · Append-only</span></div><section class="panel"><form class="filter-bar" @submit.prevent="cursor=null;refresh()"><span class="search-input"><i class="pi pi-search"></i><InputText v-model="search" placeholder="Tìm thao tác hoặc người thực hiện…"/></span><Button type="submit" label="Tìm nhật ký" icon="pi pi-search" outlined/><Button label="Về mới nhất" text severity="secondary" @click="cursor=null;refresh()"/></form><QueryState :loading="loading" :error="error" @retry="refresh"/><DataTable v-if="data" :value="data.items" class="grap-table"><template #empty><div class="table-empty">Không có nhật ký phù hợp.</div></template><Column header="THỜI ĐIỂM"><template #body="{data:d}">{{date(d.createdAt)}}</template></Column><Column header="NGƯỜI THỰC HIỆN"><template #body="{data:d}"><div class="person-cell"><span class="avatar small mint">{{initials(d.actorName)}}</span><strong>{{d.actorName}}</strong></div></template></Column><Column header="THAO TÁC"><template #body="{data:d}"><code class="action-code">{{d.action}}</code></template></Column><Column header="LÝ DO"><template #body="{data:d}"><span class="audit-reason">{{d.reason||'—'}}</span></template></Column><Column header="TRACE"><template #body="{data:d}"><span class="trace-id" :title="d.traceId">{{d.traceId?.slice(0,12)||'—'}}</span></template></Column></DataTable><div class="pagination"><span>{{data?.items.length??0}} bản ghi / trang</span><Button label="Tải trang tiếp" icon="pi pi-arrow-right" icon-pos="right" text :disabled="!data?.nextCursor" @click="cursor=data?.nextCursor;refresh()"/></div></section></template>
